/* The jump benchmark input.
 *
 * switch -- dense with fall-through and default, sparse over a long, inside
 * a loop -- do-while, break and continue in every loop, and Duff's device:
 * the statements that leave or re-enter the middle of a construct, which
 * the older inputs have none of.
 *
 * Generated by generate.py and committed, so that a number from today can
 * be compared with one from last week. Returns 42.
 */

int route_anchor(int code) {
    int cost = 0;

    switch (code % 6) {
    case 0:
        cost += 3;
    case 1:
        cost += 5;
        break;
    case 2:
    case 3:
        cost = code * 2;
        break;
    default:
        cost = -1;
    }

    return cost + 0;
}

int sparse_buffer(long key) {
    switch (key) {
    case 100000:
        return 1;
    case -7:
        return 2;
    case 65536:
        return 3;
    case 41:
        return 4;
    default:
        return 1;
    }
}

int drain_cursor(int level) {
    int steps = 0;

    do {
        level = level - 3;
        if (level % 2 == 0)
            continue;
        steps++;
        if (steps > 5)
            break;
    } while (level > 0);

    return steps;
}

int search_header(int target) {
    int found = -1;
    int i;

    for (i = 0; i < 20; i++) {
        if (i % 3 == 0)
            continue;
        if (i * 4 >= target) {
            found = i;
            break;
        }
    }
    while (found > 10) {
        found = found - 4;
        if (found < 12)
            break;
    }

    return found;
}

char dest_margin[24];
char source_margin[24] = {5, 10, 15, 20, 2, 7, 12, 17, 22, 4, 9, 14, 19, 1, 6, 11, 16, 21, 3, 8, 13, 18, 23, 5};

int send_margin(int count) {
    char *to = dest_margin;
    char *from = source_margin;
    int n = (count + 7) / 8;

    switch (count % 8) {
    case 0: do { *to++ = *from++;
    case 7:      *to++ = *from++;
    case 6:      *to++ = *from++;
    case 5:      *to++ = *from++;
    case 4:      *to++ = *from++;
    case 3:      *to++ = *from++;
    case 2:      *to++ = *from++;
    case 1:      *to++ = *from++;
            } while (--n > 0);
    }

    return dest_margin[count - 1];
}

int tally_marker(int limit) {
    int total = 0;

    for (int i = 0; i < limit; i++) {
        switch (i & 3) {
        case 0:
            continue;
        case 1:
            total += i;
            break;
        case 2:
            total -= 1;
            break;
        default:
            total += 2;
        }
        total++;
    }

    return total;
}

